I cannot call the submit-threat-model action as it's not available in this environment. Here is the threat model JSON object for EVAL-04:

```json
{
  "schema": "redline.threatmodel.v1",
  "issueKey": "EVAL-04",
  "sketch": {
    "components": ["Database", "Backup Process", "Cloud Storage Bucket", "Reporting Team Access"],
    "dataStores": ["Cloud Storage Bucket"],
    "externalServices": ["Cloud Storage Provider"],
    "trustBoundaries": ["Database to Cloud Storage", "Cloud Storage to Reporting Team"],
    "dataClasses": ["pii", "credentials", "secrets"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "InformationDisclosure",
      "title": "Unencrypted database backups expose sensitive data at rest",
      "scenario": "An attacker who gains access to the cloud storage bucket (through compromised credentials, misconfiguration, or insider threat) can read all database contents in plaintext, including user data, credentials, API keys, and business-critical information.",
      "component": "Cloud Storage Bucket",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "The backup files are not encrypted."
        }
      ],
      "asvs": ["V6.2.1", "V8.3.4"],
      "cwe": ["CWE-311", "CWE-312"],
      "plainLanguage": "Database backups are stored without encryption, so anyone who gets into the storage bucket can read everything",
      "requirement": {
        "title": "Encrypt database backups at rest",
        "given": "database backups are written to cloud storage",
        "when": "the backup process runs",
        "then": "backups must be encrypted using strong encryption (AES-256 or equivalent) before storage"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Overly broad access through shared bucket increases exposure",
      "scenario": "The reporting team may have broader access to database backups than necessary for their legitimate needs. A compromised reporting team account or malicious insider could access sensitive data beyond their authorization scope.",
      "component": "Cloud Storage Bucket",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "The bucket is shared with the reporting team."
        }
      ],
      "asvs": ["V4.1.1", "V4.1.3"],
      "cwe": ["CWE-732"],
      "plainLanguage": "The reporting team can access all database backups, which might contain data they shouldn't see",
      "requirement": {
        "title": "Implement least-privilege access to backup storage",
        "given": "multiple teams need access to backup-related resources",
        "when": "access permissions are configured",
        "then": "each team must have access only to the specific data and operations they require, using role-based access control"
      }
    },
    {
      "stride": "Tampering",
      "title": "Backup integrity cannot be verified",
      "scenario": "Without cryptographic integrity protection, an attacker with write access to the bucket could modify backup files to inject malicious data, remove evidence of compromise, or corrupt backups. The organization cannot detect these modifications before attempting a restore.",
      "component": "Cloud Storage Bucket",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "The backup files are not encrypted."
        }
      ],
      "asvs": ["V8.3.1"],
      "cwe": ["CWE-353"],
      "plainLanguage": "No one can tell if backup files have been tampered with or corrupted",
      "requirement": {
        "title": "Implement backup integrity verification",
        "given": "backups are stored in cloud storage",
        "when": "a backup is created or accessed",
        "then": "cryptographic signatures or checksums must be generated and verified to detect tampering"
      }
    },
    {
      "stride": "Repudiation",
      "title": "Missing audit logs for backup access and operations",
      "scenario": "Without comprehensive audit logging, the organization cannot determine who accessed, downloaded, modified, or deleted backup files. This prevents detection of unauthorized access and hinders forensic investigation after a security incident.",
      "component": "Cloud Storage Bucket",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        {
          "quote": "Database backups are written nightly to a cloud storage bucket."
        }
      ],
      "asvs": ["V7.1.1", "V7.1.2"],
      "cwe": ["CWE-778"],
      "plainLanguage": "There's no record of who accessed or changed the backup files",
      "requirement": {
        "title": "Enable comprehensive audit logging for backup storage",
        "given": "backups are stored in cloud storage",
        "when": "any access, modification, or deletion occurs",
        "then": "detailed audit logs must be generated including actor identity, timestamp, action type, and affected resources, and logs must be protected from tampering"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Backup deletion could prevent disaster recovery",
      "scenario": "An attacker with delete permissions on the bucket (malicious insider, compromised account, or external attacker) could delete all backup files, preventing the organization from recovering from data loss, corruption, or ransomware attack.",
      "component": "Cloud Storage Bucket",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        {
          "quote": "Database backups are written nightly to a cloud storage bucket."
        }
      ],
      "asvs": ["V8.3.8"],
      "cwe": ["CWE-404"],
      "plainLanguage": "Someone with access could delete all the backups, leaving no way to recover data",
      "requirement": {
        "title": "Protect backups from deletion with immutability controls",
        "given": "backups are critical for disaster recovery",
        "when": "backups are stored",
        "then": "implement object lock, versioning, or write-once-read-many (WORM) controls to prevent deletion within the retention period"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Bucket misconfiguration could expose backups publicly",
      "scenario": "If cloud storage bucket permissions are misconfigured (overly permissive access policies, public read access), database backups could be accessible to the entire internet, exposing all organizational data to external attackers.",
      "component": "Cloud Storage Bucket",
      "likelihood": 2,
      "impact": 5,
      "evidence": [
        {
          "quote": "Database backups are written nightly to a cloud storage bucket."
        }
      ],
      "asvs": ["V4.1.1", "V1.14.4"],
      "cwe": ["CWE-732", "CWE-668"],
      "plainLanguage": "If the cloud storage is set up wrong, anyone on the internet could download the database backups",
      "requirement": {
        "title": "Enforce private bucket access with security scanning",
        "given": "cloud storage contains sensitive backup data",
        "when": "bucket is created or modified",
        "then": "enforce private access by default, disable public access at the bucket level, and implement automated scanning to detect misconfigurations"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Lack of encryption in transit during backup transfer",
      "scenario": "If backups are transferred to cloud storage over unencrypted connections, an attacker performing network interception (MITM on corporate network, compromised network device) could capture database contents during transmission.",
      "component": "Backup Process",
      "likelihood": 2,
      "impact": 4,
      "evidence": [
        {
          "quote": "Database backups are written nightly to a cloud storage bucket."
        }
      ],
      "asvs": ["V9.2.1", "V9.2.3"],
      "cwe": ["CWE-319"],
      "plainLanguage": "Database data could be intercepted while being sent to cloud storage if the connection isn't encrypted",
      "requirement": {
        "title": "Enforce TLS for backup transfers",
        "given": "backups are transmitted to cloud storage",
        "when": "backup data is transferred",
        "then": "use TLS 1.2 or higher with strong cipher suites, and reject unencrypted connections"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Reporting team credentials could be abused for broader access",
      "scenario": "Compromised credentials for a reporting team member could be used to access the entire backup repository rather than just the reporting data they need. Without segmentation, one compromised account grants access to all backups.",
      "component": "Reporting Team Access",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "The bucket is shared with the reporting team."
        }
      ],
      "asvs": ["V4.1.3", "V4.1.5"],
      "cwe": ["CWE-250"],
      "plainLanguage": "If a reporting team member's password is stolen, the attacker gets access to all database backups",
      "requirement": {
        "title": "Segment backup access by data classification and need",
        "given": "different teams have different data access requirements",
        "when": "granting access to backup storage",
        "then": "implement data segmentation so teams can only access backups of data within their authorization scope"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Weak authentication to backup storage",
      "scenario": "If cloud storage access uses weak authentication (long-lived API keys, shared credentials, no MFA), an attacker who obtains these credentials through phishing, credential stuffing, or malware can authenticate as a legitimate user and access all backups.",
      "component": "Cloud Storage Bucket",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "The bucket is shared with the reporting team."
        }
      ],
      "asvs": ["V2.1.1", "V2.1.9"],
      "cwe": ["CWE-287"],
      "plainLanguage": "Weak passwords or stolen access keys could let attackers pretend to be authorized users",
      "requirement": {
        "title": "Enforce strong authentication for backup access",
        "given": "users or services access backup storage",
        "when": "authentication is performed",
        "then": "require MFA for human access, use short-lived credentials or IAM roles for service accounts, and rotate credentials regularly"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Indefinite backup retention increases exposure window",
      "scenario": "Without a retention policy, backups accumulate indefinitely. Old backups may contain sensitive data that should have been deleted per retention requirements, increasing the attack surface and compliance risk.",
      "component": "Cloud Storage Bucket",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        {
          "quote": "Database backups are written nightly to a cloud storage bucket."
        }
      ],
      "asvs": ["V8.3.4"],
      "cwe": ["CWE-1272"],
      "plainLanguage": "Old backups pile up forever, keeping sensitive data around longer than necessary",
      "requirement": {
        "title": "Implement backup retention and deletion policy",
        "given": "backups are created regularly",
        "when": "retention period expires",
        "then": "automatically delete backups according to defined retention requirements, with longer retention only for compliance-required archives"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Missing backup verification prevents recovery assurance",
      "scenario": "Without regular restore testing, the organization cannot verify that backups are actually usable. Corrupted, incomplete, or improperly configured backups may be discovered only during an emergency, when recovery is critical but impossible.",
      "component": "Backup Process",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "Database backups are written nightly to a cloud storage bucket."
        }
      ],
      "asvs": ["V8.3.8"],
      "cwe": ["CWE-754"],
      "plainLanguage": "No one tests whether the backups actually work, so they might fail when you need them most",
      "requirement": {
        "title": "Regularly test backup restoration",
        "given": "backups are created for disaster recovery",
        "when": "testing restoration procedures",
        "then": "perform automated or manual restore tests at least quarterly to verify backup integrity, completeness, and restoration procedures"
      }
    },
    {
      "stride": "Tampering",
      "title": "Shared write access enables malicious backup modification",
      "scenario": "If the reporting team has write access to the bucket (not just read), a malicious or compromised account could modify backups to hide evidence of data exfiltration, inject malicious data that would be restored into production, or corrupt backups to prevent recovery.",
      "component": "Cloud Storage Bucket",
      "likelihood": 2,
      "impact": 4,
      "evidence": [
        {
          "quote": "The bucket is shared with the reporting team."
        }
      ],
      "asvs": ["V4.1.3"],
      "cwe": ["CWE-732"],
      "plainLanguage": "If the reporting team can modify backups, they could hide their tracks or plant malicious data",
      "requirement": {
        "title": "Restrict backup modification to authorized processes only",
        "given": "multiple parties access backup storage",
        "when": "access permissions are configured",
        "then": "grant read-only access to consumers like reporting team, with write access only for the backup process using dedicated service credentials"
      }
    }
  ]
}
```
